def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_last, opp_last = history[-1]
    if n == 1:
        return 'C' if opp_last == 'C' else 'D'

    opp_c = 0
    for me, op in history:
        if op == 'C':
            opp_c += 1
    opp_d = n - opp_c

    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    unprov = 0
    unprov_runs = 0
    prev_unprov = False
    after_my_d = 0
    coop_after_d = 0

    for i in range(1, n):
        cur = (history[i - 1][0] == 'C' and history[i][1] == 'D')
        if cur:
            unprov += 1
            if not prev_unprov:
                unprov_runs += 1
        prev_unprov = cur

        if history[i - 1][0] == 'D':
            after_my_d += 1
            if history[i][1] == 'C':
                coop_after_d += 1

    # Repeated unprovoked bursts are best met by exploiting/defecting.
    if n >= 15 and unprov_runs >= 2 and unprov >= 3 and opp_c > 0:
        return 'D'

    # If the opponent often forgives our defections, exploit that.
    if after_my_d >= 4 and coop_after_d * 3 >= after_my_d * 2:
        return 'D'

    # Near-always-cooperative opponents: mostly reciprocate, but exploit
    # pure unconditional cooperators after a short probation.
    if opp_c >= n - 2 and opp_last == 'C':
        if opp_c == n and n >= 30:
            return 'D'
        return 'C'

    # Against overwhelmingly defective opponents, defect.
    if opp_c <= 2 and n >= 8:
        return 'D'

    # Forgive a single unprovoked defection from an otherwise very cooperative
    # opponent, and recover quickly after short mutual-defection bursts.
    if opp_last == 'D' and same_count == 1 and opp_c >= n - 2:
        return 'C'

    # After a short fixed burst of four defections from a mostly cooperative
    # opponent, switch back to cooperation to restore mutual cooperation.
    if opp_last == 'D' and same_count >= 4:
        if same_count == 4 and opp_c >= opp_d:
            return 'C'
        if same_count >= 5 and opp_c >= opp_d * 2:
            return 'C'
        if rng.randint(0, 3) == 0:
            return 'C'
        return 'D'

    # Generous recovery from very short retaliation loops.
    if opp_last == 'D' and my_last == 'C' and same_count <= 2 and opp_c >= opp_d + 2:
        return 'C'

    # Standard defection response: mostly punish, with some forgiveness.
    if opp_last == 'D':
        if my_last == 'D' and same_count <= 2 and opp_c >= opp_d * 2:
            if rng.randint(0, 2) == 0:
                return 'C'
        if n < 95 and rng.randint(0, 6) == 0:
            return 'C'
        return 'D'

    # Opponent cooperated.
    if same_count >= 5:
        if n < 90 and opp_c >= n - 5:
            if rng.randint(0, 9) == 0:
                return 'D'
        return 'C'

    if my_last == 'D' and n < 95 and rng.randint(0, 4) == 0:
        return 'D'
    return 'C'
